function buildPrompt(displayName: string, description: string): string {
  const metadataMatch = description.match(/METADATA:\{([^}]+)\}/)
  const role = description.replace(/\s*METADATA:\{[^}]+\}/, '').trim()
  const fields = metadataMatch ? metadataMatch[1] : 'query,response,escalated'
  return `You are the ${displayName} for LYCHO. ${role} LANGUAGE: Auto-detect and respond in the visitor's language automatically. TONE: Professional, empathetic, and solution-focused. Human Sovereignty: Escalate to humans when issues are urgent, high-value, emotionally sensitive, or beyond your scope. Always ask before making commitments. METADATA: extract {${fields}}.`
}

export const ALL_AGENTS_PROMPTS: Record<string, string> = Object.fromEntries(
  AGENT_DATA.map(([type, name, description]) => [type, buildPrompt(name, description)])
)

export const ALL_AGENTS_META: Record<string, { display_name: string; description: string }> = Object.fromEntries(
  AGENT_DATA.map(([type, name, description]) => {
    const role = description.replace(/\s*METADATA:\{[^}]+\}/, '').trim()
    return [type, { display_name: name, description: role.split('.')[0] }]
  })
)
